If you cannot upgrade, then you can either:

  *  Remove Spring Vault from the classpath if it is not needed or
  *  Implement your own SessionManager that does not persist the Vault token and provide a bean using that implementation in a @Configuration class. For example:


public class StatelessSessionManager implements SessionManager {

  private final ClientAuthentication clientAuthentication;

  private final ReentrantLock lock = new ReentrantLock();

  public StatelessSessionManager(ClientAuthentication clientAuthentication) {
    Assert.notNull(clientAuthentication, "ClientAuthentication must not be null");
    this.clientAuthentication = clientAuthentication;
  }

  public VaultToken getSessionToken() {
    this.lock.lock();
    try {
      return this.clientAuthentication.login();
    }
    finally {
      this.lock.unlock();
    }
  }

}

@Configuration
public class MySessionManagerConfiguration extends SpringVaultClientConfiguration {

  private final VaultEnvironmentProperties vaultProperties;

  public MySessionManagerConfiguration(VaultEnvironmentProperties vaultProperties, ConfigTokenProvider configTokenProvider, List<springvaultclientauthenticationprovider> authProviders) {
    super(vaultProperties, configTokenProvider, authProviders);
    this.vaultProperties = vaultProperties;
  }

